199	      // side-effect handoff to the OS; it never touches [state]/[emit], so
200	      // there's no encapsulation reason to skip it once [isClosed] (unlike
201	      // [_poll]'s own `isClosed` guard, which exists specifically to avoid
202	      // emitting after disposal). Short-circuiting here used to silently
203	      // drop the user's download the instant they dismissed the sheet.
204	      return await result.match((failure) async => failure, (url) async {
205	        try {
206	          final opened = await _downloadOpener.open(url);
207	          return opened
208	              ? null
209	              : const Failure.malformedResponse(
210	                  message: _downloadFailureMessage,
211	                );
212	        } catch (_) {
213	          // [DownloadOpener]'s own contract never promises it won't throw
214	          // — the real `UrlLauncherDownloadOpener` already catches
215	          // internally, but nothing enforces that on the port itself
216	          // (review finding, patch item 5). RNF09: never let a thrown
217	          // exception escape uncaught out of `_handleDownload`'s own
218	          // unguarded `await`.
219	          return const Failure.malformedResponse(
220	            message: _downloadFailureMessage,
221	          );
222	        }
223	      });
224	    } finally {
225	      _downloadsInFlight.remove(format);
226	    }
227	  }
